private int decodeOctet(final byte octet) {

        int decoded = -1;

        if ((octet & 0xff) < decodeTable.length) {

            decoded = decodeTable[octet];

        }



        if (decoded == -1) {

            throw new IllegalArgumentException("Invalid octet in encoded value: " + (int)octet);

        }



        return decoded;

    }
